CREATE OR REPLACE PROCEDURE sp(
    para_Location    IN VARCHAR2,
    para_Fate        IN VARCHAR2,
    para_Speed_knots IN NUMBER,
    para_Ship_ID     IN NUMBER
) IS
    CURSOR c_mission IS
        SELECT * FROM mission
        WHERE Location > para_Location
        FOR UPDATE;
    v_avg_speed NUMBER;
BEGIN
    -- Step 1: cursor-selected rows get Fate updated
    FOR r IN c_mission LOOP
        UPDATE mission SET Fate = para_Fate WHERE CURRENT OF c_mission;
    END LOOP;

    -- Step 2: delete rows with NULL or strictly below para_Speed_knots
    DELETE FROM mission
    WHERE Speed_knots IS NULL OR Speed_knots < para_Speed_knots;

    -- Step 3: delete rows strictly below the average of remaining rows
    SELECT AVG(Speed_knots) INTO v_avg_speed FROM mission;
    DELETE FROM mission WHERE Speed_knots < v_avg_speed;

    -- Step 4: update Ship_ID on all remaining rows
    UPDATE mission SET Ship_ID = para_Ship_ID;
END sp;
/

